// Select: React Aria (button + popover + list), simple options-based API. Generated by shadcn and trimmed.
// An option may carry an icon (an agent's face): it shows in the list and on the trigger. Past SEARCH_AT options a
// search field sits on top of the list (React Aria's Autocomplete), so a long list (hundreds of agents) stays usable.
import { CheckIcon, ChevronDownIcon } from "lucide-react"
import type { ReactNode } from "react"
import { Autocomplete, Button, ListBox, ListBoxItem, Popover, SearchField, Select as SelectPrimitive, SelectValue, useFilter } from "react-aria-components"
import { cn } from "@/lib/utils"
import { field, SearchInput } from "./input"

export type SelectOption = { value: string; label: string; icon?: ReactNode }

const SEARCH_AT = 8

// React Aria keys can't be empty; "" (e.g. "Sem agente") becomes "v:".
const key = (v: string) => `v:${v}`

export function Select({
  value,
  onChange,
  options,
  placeholder,
  size = "md",
  variant = "field",
  icon,
  className,
  "aria-label": ariaLabel,
  searchLabel,
  emptyLabel
}: {
  value: string
  onChange: (value: string) => void
  options: ReadonlyArray<SelectOption>
  placeholder?: string
  size?: "sm" | "md"
  // field: a form field (border, surface). ghost: a quiet trigger beside a composer, like the model picker's.
  variant?: "field" | "ghost"
  icon?: ReactNode
  className?: string
  "aria-label"?: string
  // The search field's label and what the list says when nothing matches (only past SEARCH_AT options).
  searchLabel?: string
  emptyLabel?: string
}) {
  const { contains } = useFilter({ sensitivity: "base" })
  const chosen = options.find((o) => o.value === value)
  const selected = chosen ? key(value) : null
  const searchable = options.length > SEARCH_AT
  const list = (
    <ListBox
      className="max-h-72 overflow-y-auto outline-none"
      items={options.map((o) => ({ ...o, id: key(o.value) }))}
      renderEmptyState={() => <p className="px-2 py-1.5 text-sm text-muted">{emptyLabel}</p>}
    >
      {(o) => (
        <ListBoxItem
          textValue={o.label}
          className={cn("relative flex h-control-sm cursor-default items-center gap-2 rounded-md pr-8 pl-2 text-secondary outline-none select-none data-focused:bg-accent-soft data-focused:text-fg data-disabled:opacity-50", size === "sm" ? "text-sm" : "text-base")}
        >
          {({ isSelected }) => (
            <>
              {o.icon && <span className="flex shrink-0 text-muted in-data-focused:text-accent-text [&_svg]:size-4">{o.icon}</span>}
              <span className="truncate">{o.label}</span>
              {isSelected && <CheckIcon className="absolute right-2 size-4 text-accent-text" />}
            </>
          )}
        </ListBoxItem>
      )}
    </ListBox>
  )
  return (
    <SelectPrimitive
      data-slot="select"
      value={selected}
      onChange={(k) => k != null && onChange(String(k).slice(2))}
      {...(placeholder !== undefined && { placeholder })}
      {...(ariaLabel !== undefined && { "aria-label": ariaLabel })}
      className={cn("w-full", className)}
    >
      <Button
        className={cn(
          variant === "ghost"
            ? "flex h-control-sm cursor-default items-center gap-1.5 rounded-control px-2.5 text-sm text-muted outline-none transition-colors duration-120 ease-out data-hovered:bg-control-hover data-hovered:text-fg data-pressed:bg-control-active popup-open:bg-control-hover popup-open:text-fg data-focus-visible:ring-2 data-focus-visible:ring-accent motion-reduce:transition-none"
            : cn(field, "flex items-center justify-between gap-1.5 text-left popup-open:border-strong", size === "sm" ? "h-control-sm px-2.5 text-sm" : "h-control")
        )}
      >
        {(chosen?.icon ?? icon) && <span className={cn("flex shrink-0", !chosen?.icon && "[&_svg]:size-4")}>{chosen?.icon ?? icon}</span>}
        <SelectValue className="flex-1 truncate text-left data-placeholder:text-dim">{({ selectedText, defaultChildren }) => selectedText ?? defaultChildren}</SelectValue>
        <ChevronDownIcon className={cn("size-4 shrink-0 transition-transform duration-120 ease-out in-popup-open:rotate-180 motion-reduce:transition-none", variant === "ghost" ? "size-3.5 opacity-70" : "text-muted")} />
      </Button>
      <Popover offset={6} className={cn("z-50 w-(--trigger-width) overflow-hidden rounded-card border border-strong bg-float shadow-float backdrop-blur-xl backdrop-saturate-150 p-1 text-fg data-entering:animate-in data-entering:fade-in-0 data-entering:zoom-in-[0.98] data-exiting:animate-out data-exiting:fade-out-0 motion-reduce:animate-none", searchable ? "min-w-64" : "min-w-40")}>
        {searchable ? (
          <Autocomplete filter={contains}>
            <SearchField aria-label={searchLabel ?? ariaLabel ?? ""} autoFocus className="mb-1">
              <SearchInput size="sm" {...(searchLabel !== undefined && { placeholder: searchLabel })} />
            </SearchField>
            {list}
          </Autocomplete>
        ) : (
          list
        )}
      </Popover>
    </SelectPrimitive>
  )
}
